run_drill() {
  local num="$1"
  local name="$2"
  local category="$3"
  local invariant="$4"
  local cmd="$5"

  TOTAL_COUNT=$((TOTAL_COUNT + 1))
  echo -e "${BOLD}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
  echo -e "${BOLD}DRILL $num: $name${NC}"
  echo -e "  ${MAGENTA}Category:${NC}  $category"
  echo -e "  ${CYAN}Invariant:${NC} $invariant"

  local start_time=$(date +%s%N)
  local output
  local status_code=0

  if output=$(eval "$cmd" 2>&1); then
    local end_time=$(date +%s%N)
    local elapsed_ms=$(( (end_time - start_time) / 1000000 ))
    echo -e "  ${GREEN}${BOLD}✓ PASSED${NC} in ${elapsed_ms}ms"
    echo -e "  ${DIM}Live Response:${NC} $(echo "$output" | head -n 3)"
    PASSED_COUNT=$((PASSED_COUNT + 1))
  else
    local end_time=$(date +%s%N)
    local elapsed_ms=$(( (end_time - start_time) / 1000000 ))
    echo -e "  ${RED}${BOLD}✗ FAILED${NC} in ${elapsed_ms}ms"
    echo -e "  ${YELLOW}Output:${NC} $(echo "$output" | head -n 5)"
  fi
  echo ""
  echo "--- DRILL $num: $name ---" >> "$DRILL_LOG"
  echo "$output" >> "$DRILL_LOG"
}

