  local probe_blocked
  probe_blocked=$(curl -s -X POST "$CLIENT_SIM_URL/simulate/probe")

  # 3. Disengage Global Lockdown via Proxy Control API
  curl -s -X POST "$PROXY_URL/v1/system/sync-lockdown" \
    -H "Content-Type: application/json" \
    -d '{"lockdownActive": false, "reason": "Drill 8 Restored"}' > /dev/null

  # 4. Client Simulator probes proxy gateway -> Must receive HTTP 200
  local probe_restored
  probe_restored=$(curl -s -X POST "$CLIENT_SIM_URL/simulate/probe")

  echo "$probe_blocked" | grep -q '"status":503' && echo "$probe_restored" | grep -q '"status":200'
}

